import json, os, glob
nodes, edges, hyper = [], [], []
for p in sorted(glob.glob('part_*.json')):
    d = json.load(open(p))
    nodes += d.get('nodes', [])
    edges += d.get('edges', [])
    hyper += d.get('hyperedges', [])

# dedupe nodes by id
seen, un = set(), []
for n in nodes:
    if n['id'] in seen: continue
    seen.add(n['id']); un.append(n)

ids = seen
REL = {"references","conceptually_related_to","shares_data_with","semantically_similar_to","rationale_for","implements","cites"}
problems = []
ue = []
eseen = set()
for e in edges:
    k = (e['source'], e['target'], e['relation'])
    if k in eseen: continue
    eseen.add(k)
    if e['source'] not in ids: problems.append(('missing src', e['source']))
    if e['target'] not in ids: problems.append(('missing tgt', e['target']))
    if e['relation'] not in REL: problems.append(('bad rel', e['relation']))
    for f in ('source','target','relation','confidence','confidence_score','source_file','source_location','weight'):
        if f not in e: problems.append(('missing field '+f, str(e)[:80]))
    if e.get('confidence')=='EXTRACTED' and e.get('confidence_score')!=1.0:
        problems.append(('extracted not 1.0', str(e)[:80]))
    if e['source']==e['target']: problems.append(('self loop', e['source']))
    ue.append(e)

for h in hyper:
    for n in h.get('nodes', []):
        if n not in ids: problems.append(('hyper missing node', n))

out = {"nodes": un, "edges": ue, "hyperedges": hyper, "input_tokens": 0, "output_tokens": 0}
json.dump(out, open('out_11.json','w'), ensure_ascii=False)
json.load(open('out_11.json'))
print("nodes", len(un), "edges", len(ue), "hyperedges", len(hyper))
print("problems:", problems[:30], "count", len(problems))
